head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// ① ② 에 공통으로 전달할 옵션
scwin.APPLY_DECIMAL = "1";
scwin.DECIMAL = "3";

// 업로드 파일의 Column 수
scwin.COL_COUNT = 4;



// 별도 팝업창으로 열린 업로드 화면의 창 핸들
scwin.popWin = null;



// 이전 케이스에서 열린 업로드 화면(WFrame 레이어 / 별도 팝업창)을 닫는다.
//  · 닫은 경우 true 를 반환한다. (닫기 처리가 끝나기 전에 다시 열면 ID 중복 경고가 발생하므로 호출부에서 간격을 둔다.)
scwin.closeOpened = function () {
    var bClosed = false;

    try {
        var objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame !== null) {
            WebSquare.util.closePopup(objFrame.id.replace("_wframe", ""));
            bClosed = true;
        }
    } catch (e) {}

    try {
        if (scwin.popWin !== null && scwin.popWin.closed === false) {
            scwin.popWin.close();
            bClosed = true;
        }
    } catch (e) {}

    scwin.popWin = null;
    return bClosed;
};



// wframe 설정 여부만 달리하여 advancedExcelUpload 실행
scwin.runCase = function (strNo, bWframe) {
    var bClosed = scwin.closeOpened();

    var fnRun = function () {
        var objOptions = { "applyDecimal" : scwin.APPLY_DECIMAL, "decimal" : scwin.DECIMAL };
        if (bWframe === true) objOptions.wframe = true;

        // wframe 미설정이면 업로드 화면이 window.open 으로 열리므로 호출 시점에만 감싸서 창 핸들을 확보한다.
        var fnOpen = window.open;
        window.open = function () {
            var objWin = fnOpen.apply(window, arguments);
            scwin.popWin = objWin;
            return objWin;
        };

        try {
            target1.advancedExcelUpload(objOptions);
        } finally {
            window.open = fnOpen;
        }

        scwin.setReturnValue("[" + strNo + "] " + (bWframe === true ? "wframe : true (WFrame 레이어)" : "wframe : 미설정 (별도 팝업창)") + " / 전달한 옵션 : applyDecimal \"" + objOptions.applyDecimal + "\" , decimal \"" + objOptions.decimal + "\"");

        // 엔진이 만든 값은 업로드가 끝나면 비워지므로 호출 직후 바로 읽는다.
        scwin.printUploadInfo();

        // 업로드 화면의 hidden 필드는 화면이 열린 뒤에 채워지므로 준비될 때까지 다시 읽는다.
        scwin.printField(bWframe, 0);
    };

    // 이전 화면의 닫기 처리가 끝난 뒤 다음 케이스를 실행한다.
    if (bClosed === true) {
        setTimeout(fnRun, 800);
    } else {
        fnRun();
    }
};



// 엔진이 만든 uploadInfo 의 applyDecimal / decimal 값 출력
scwin.printUploadInfo = function () {
    var strInfo = target1._excelUploadInfo;
    if (strInfo === undefined || strInfo === null || strInfo === "") {
        scwin.setReturnValue("엔진이 만든 uploadInfo : 확인 불가");
        return;
    }

    var objInfo = JSON.parse(strInfo);
    scwin.setReturnValue("엔진이 만든 uploadInfo : applyDecimal " + JSON.stringify(objInfo.applyDecimal) + " , decimal " + JSON.stringify(objInfo.decimal));
};



// 업로드 화면의 hidden 필드 값을 읽는다. (준비 전이면 null)
scwin.readField = function (bWframe, strName) {
    if (bWframe === true) {
        var objInput = document.querySelector("input[id$='_excelPop_wframe_" + strName + "']");
        if (objInput === null) return null;
        return objInput.value;
    }

    if (scwin.popWin === null || scwin.popWin.closed === true) return null;

    var objDoc = scwin.popWin.document;
    if (objDoc === null) return null;

    var objInput2 = objDoc.getElementById(strName);
    if (objInput2 === null) return null;
    return objInput2.value;
};



// 업로드 화면(WFrame 레이어 / 별도 팝업창)의 applyDecimal / decimal 필드 값 출력
scwin.printField = function (bWframe, nTry) {
    var strApply = null;
    var strDecimal = null;

    try {
        strApply = scwin.readField(bWframe, "applyDecimal");
        strDecimal = scwin.readField(bWframe, "decimal");
    } catch (e) {}

    // decimal 필드가 채워지면 화면이 준비된 것으로 본다.
    if ((strDecimal === null || strDecimal === "") && nTry < 60) {
        setTimeout(function () {
            scwin.printField(bWframe, nTry + 1);
        }, 250);
        return;
    }

    scwin.setReturnValue("업로드 화면의 applyDecimal 필드 : " + (strApply === null ? "확인 불가" : "\"" + strApply + "\"") + " / decimal 필드 : " + (strDecimal === null ? "확인 불가" : "\"" + strDecimal + "\""));
};



// 업로드 완료 후 GridView 에 반영된 Row / Column 값 출력
scwin.target1_onfilereadend = function (value) {
    var nRow = dlt_upload.getRowCount();

    for (var i = 0; i < nRow; i++) {
        var arrCol = [];
        for (var j = 0; j < scwin.COL_COUNT; j++) {
            var strVal = target1.getCellData(i, "col" + j);
            if (strVal === undefined || strVal === null || strVal === "") strVal = "-";
            arrCol.push(strVal);
        }
        scwin.setReturnValue("Row " + i + " : " + arrCol.join(" | "));
    }

    scwin.setReturnValue("");
};



// ① wframe 미설정
scwin.btn_case1_onclick = function () {
    scwin.runCase("①", false);
};

// ② wframe true
scwin.btn_case2_onclick = function () {
    scwin.runCase("②", true);
};
